using ll = long long;

const int N = 254;
const ll MOD = 1000000007LL;

ll dp[N][N];
ll C[N][N];

ll bigpow(ll a, ll b) {
    a %= MOD;
    ll result = 1;
    while (b > 0) {
        if (b & 1LL) result = result * a % MOD;
        a = a * a % MOD;
        b >>= 1LL;
    }
    return result;
}

ll calc(ll r, ll c, ll k, ll n) {
    if (dp[r][c] != -1) return dp[r][c];
    if (r == 0) return dp[r][c] = 1;

    if (c == 0) {
        ll tmp = (bigpow(k, n) - bigpow(k - 1, n) + MOD) % MOD;
        return dp[r][c] = bigpow(tmp, r);
    }

    if (r == 1) {
        return dp[r][c] = bigpow(k, n - c);
    }

    ll res = (bigpow(k, n - c) - bigpow(k - 1, n - c) + MOD) % MOD;
    res = res * bigpow(k - 1, c) % MOD;
    res = res * calc(r - 1, c, k, n) % MOD;

    for (ll c0 = 1; c0 <= c; ++c0) {
        ll tmp = bigpow(k, n - c) * C[c][c0] % MOD;
        tmp = tmp * bigpow(k - 1, c - c0) % MOD;
        tmp = tmp * calc(r - 1, c - c0, k, n) % MOD;
        res = (res + tmp) % MOD;
    }

    return dp[r][c] = res;
}

